// --- drawing helpers ---------------------------------------------------
// A colour is 'RRGGBB' or ['RRGGBB', transparencyPct].
const paint = c => (Array.isArray(c) ? { color: c[0], transparency: c[1] } : { color: c });
const stroke = l => (l
  ? { color: l[0], width: l.length > 1 ? l[1] : 1, transparency: l[2] || 0 }
  : { type: 'none' });

// Inside a component the geometry is expressed in 0..1 of the component box;
// p() maps such a rectangle onto the box the component was placed in.
let BOX = [0, 0, 1, 1];
const p = (x, y, w, h) => [BOX[0] + x * BOX[2], BOX[1] + y * BOX[3], w * BOX[2], h * BOX[3]];
function place(fn) {
  return function (s, x, y, w, h) {
    const prev = BOX;
    BOX = [x, y, w, h];
    fn(s);
    BOX = prev;
  };
}

function base(x, y, w, h, o) {
  const opt = { x: x, y: y, w: w, h: h, line: stroke(o.line) };
  opt.fill = o.fill !== undefined ? paint(o.fill) : { type: 'none' };
  if (o.ra) opt.rectRadius = o.ra * Math.min(w, h);
  if (o.rot) opt.rotate = o.rot;
  if (o.fh) opt.flipH = true;
  if (o.fv) opt.flipV = true;
  return opt;
}

// Preset shape: shp(slide, kind, x, y, w, h, {fill, line, ra, rot, fh, fv})
function shp(s, kind, x, y, w, h, o) {
  o = o || {};
  const opt = base(x, y, w, h, o);
  if (kind === 'line') { opt.line = stroke(o.line || [WHITE]); delete opt.fill; }
  s.addShape(kind, opt);
}

// Free-form outline from OUTLINES, scaled into the x/y/w/h box.
function path(s, name, x, y, w, h, o) {
  o = o || {};
  const opt = base(x, y, w, h, o);
  opt.points = OUTLINES[name].map(c =>            // points are box-relative
    c[0] === 'M' ? { x: c[1] * w, y: c[2] * h, moveTo: true }
    : c[0] === 'L' ? { x: c[1] * w, y: c[2] * h }
    : c[0] === 'C' ? { x: c[5] * w, y: c[6] * h,
        curve: { type: 'cubic', x1: c[1] * w, y1: c[2] * h, x2: c[3] * w, y2: c[4] * h } }
    : { close: true });
  s.addShape('custGeom', opt);
}

// pptxgenjs has no gradient fill, so gradients are painted as colour bands.
const blend = (c1, c2, t) => [0, 2, 4].map(k => Math.round(
    parseInt(c1.substr(k, 2), 16) * (1 - t) + parseInt(c2.substr(k, 2), 16) * t)
  .toString(16).padStart(2, '0')).join('').toUpperCase();

// Vertical gradient: the violet-to-pink rail down the left edge of every slide.
function vgrad(s, x, y, w, h, c1, c2, bands) {
  for (let i = 0; i < bands; i++) {
    shp(s, 'rect', x, y + (h * i) / bands, w, h / bands + 0.02,
      { fill: blend(c1, c2, i / (bands - 1)) });
  }
}

// Diagonal glow in the bottom-right corner of the deep-blue background,
// built from nested right triangles.
function dgrad(s, w, h, c1, c2, bands) {
  for (let i = bands; i >= 1; i--) {
    const t = i / bands;
    shp(s, 'rtTriangle', w - w * t, h - h * t, w * t, h * t,
      { fill: blend(c1, c2, 1 - t), fh: 1 });
  }
}

// Stand-in for a photograph in the source deck.
function img(s, x, y, w, h, o) {
  o = o || {};
  if (o.p) path(s, o.p, x, y, w, h, { fill: GREY });
  else shp(s, o.sh || 'rect', x, y, w, h, { fill: GREY, ra: o.ra });
}

// Text box.  t is a string, or an array of [text, runOptions] pairs.
// o = {sz, col, b, al:'c'|'r'|'j', va:'m', ls, fill, sh, ra, rot}
function txt(s, t, x, y, w, h, o) {
  o = o || {};
  const runs = (typeof t === 'string' ? [[t]] : t).map(r => {
    const q = r[1] || {};
    return { text: r[0], options: {
      fontSize: q.sz || o.sz || 12, color: q.col || o.col || WHITE,
      bold: q.b !== undefined ? !!q.b : !!o.b, italic: !!q.i,
      underline: q.u ? { style: 'sng' } : undefined, superscript: !!q.sup,
      breakLine: !!q.br } };
  });
  const opt = base(x, y, w, h, o);
  Object.assign(opt, { fontFace: FONT, fontSize: o.sz || 12, color: o.col || WHITE, bold: !!o.b,
    margin: [MARG, MARG, MARG, MARG], isTextBox: !o.sh, shape: o.sh || 'rect',
    align: { c: 'center', r: 'right', j: 'justify' }[o.al] || 'left',
    valign: o.va === 'm' ? 'middle' : 'top' });
  if (o.ls) opt.lineSpacingMultiple = o.ls;
  if (o.af) opt.fit = 'resize';         // <a:spAutoFit/> as in the source deck
  s.addText(runs, opt);
}

